// Literal port of the team's Casa3DSDK (module house/helpers). Generated by codemod and reviewed; see MIGRATION.md.
import type { Kernel, Shared } from '../kernel-types.js';

export function installHouseHelpers(K: Kernel, shared: Shared): void {
  // ---------------- 30 house ----------------
  // ===== house: walls with gaps, doors, windows, floors, slabs, ceilings, stairs, elevator, furniture =====
  shared.ctx = {};
   // context of the house being built/used (enter(h) switches between houses)
  const OPEN_ROOM_TYPES = new Set(['balcony', 'terrace', 'veranda', 'balcony_gourmet']);
  const NO_CEILING = OPEN_ROOM_TYPES;
  const OPEN_AREA = c => OPEN_ROOM_TYPES.has(c.type) || c.outdoor === true;
   // open area: no roof or ceiling
  const EPS = 1e-3;
  const Y0 = f => { const A = shared.ctx.r.floors; return A[Math.max(0, Math.min(A.length - 1, f))].y0; };
  const colorOf = v => (typeof v === 'number' ? v : (typeof v === 'string' && shared.ctx.colors[v] != null ? shared.ctx.colors[v] : null));
  const rectsOf = c => (c.parts && c.parts.length ? c.parts : [[c.u0, c.v0, c.u1, c.v1]]);
  function roomAt(f, u, v) { for (const c of shared.ctx.r.rooms) if (c.floor === f) for (const [a, b, c2, d] of rectsOf(c)) if (u > a + EPS && u < c2 - EPS && v > b + EPS && v < d - EPS) return c; return null; }
  function subRect(a, b) { // a minus b (rectangles [u0,v0,u1,v1])
    const [ax0, az0, ax1, az1] = a, [bx0, bz0, bx1, bz1] = b;
    if (bx0 >= ax1 - EPS || bx1 <= ax0 + EPS || bz0 >= az1 - EPS || bz1 <= az0 + EPS) return [a];
    const o = [];
    if (bz0 > az0 + EPS) o.push([ax0, az0, ax1, bz0]); if (bz1 < az1 - EPS) o.push([ax0, bz1, ax1, az1]);
    const z0 = Math.max(az0, bz0), z1 = Math.min(az1, bz1);
    if (bx0 > ax0 + EPS) o.push([ax0, z0, bx0, z1]); if (bx1 < ax1 - EPS) o.push([bx1, z0, ax1, z1]);
    return o;
  }
  function subRects(rs, holes) { let L = rs; for (const h of holes) L = L.flatMap(r => subRect(r, h)); return L; }
  const wallColor = c => (c && c.color && colorOf(c.color.wall) != null ? colorOf(c.color.wall) : 0xe4e0d8);
  const floorColor = c => (c && c.color && colorOf(c.color.floor) != null ? colorOf(c.color.floor) : 0xb0a898);
  function stairFootprint(m) { // stair rectangle [u0,v0,u1,v1] (front = local +z)
    const c = Math.cos(m.ry), s = Math.sin(m.ry), pts = [[-m.w / 2, -m.d / 2], [m.w / 2, -m.d / 2], [m.w / 2, m.d / 2], [-m.w / 2, m.d / 2]].map(([a, b]) => [m.x + a * c + b * s, m.z - a * s + b * c]);
    return [Math.min(...pts.map(p => p[0])), Math.min(...pts.map(p => p[1])), Math.max(...pts.map(p => p[0])), Math.max(...pts.map(p => p[1]))];
  }
  function effectiveHeight(f, h) { const A = shared.ctx.r.floors; if (f + 1 >= A.length) return h; const pitch = A[f + 1].y0 - A[f].y0; return h > pitch && h - pitch <= 0.45 ? pitch : h; }
  Object.assign(K, { OPEN_ROOM_TYPES, NO_CEILING, OPEN_AREA, EPS, Y0, colorOf, rectsOf, roomAt, subRect, subRects, wallColor, floorColor, stairFootprint, effectiveHeight });
}
